/**
 * Pulls every map from valorant-api.com, distills it into a tactical-board
 * friendly shape and writes it to `lib/generated/valorant-maps.ts`.
 *
 * Usage:
 *   bun run sync:maps
 *
 * The generated file exposes:
 *   - `VALORANT_MAPS` — full per-map metadata (multipliers, callouts).
 *   - `getMapScale(mapName)` — minimap scale for ability sizing.
 *   - `worldToMinimap(x, y, mapName)` — converts in-game UE coords to a
 *     0..1 fraction of the minimap.
 *
 * The Riot client uses the formula:
 *   minimap = world * multiplier + scalar
 * which is exactly what the API provides per map. 1 in-game meter ≈ 100
 * Unreal Units, so `metersPerMinimap = 1 / (xMultiplier * 100)`.
 */
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";

interface ApiCalloutLocation {
  x: number;
  y: number;
  z: number;
}

interface ApiCallout {
  regionName: string;
  superRegion: string | null;
  superRegionName: string | null;
  location: ApiCalloutLocation | null;
}

interface ApiMap {
  uuid: string;
  displayName: string;
  mapUrl: string;
  xMultiplier: number;
  yMultiplier: number;
  xScalarToAdd: number;
  yScalarToAdd: number;
  callouts: ApiCallout[] | null;
}

interface ApiResponse {
  status: number;
  data: ApiMap[];
}

const OUT_DIR = path.join(process.cwd(), "lib", "generated");
const OUT_FILE = path.join(OUT_DIR, "valorant-maps.ts");

async function main() {
  const response = await fetch("https://valorant-api.com/v1/maps");
  if (!response.ok) {
    throw new Error(`valorant-api.com responded ${response.status}`);
  }
  const json = (await response.json()) as ApiResponse;

  const playable = json.data.filter(
    (m) => m.xMultiplier !== 0 && m.callouts && m.callouts.length > 0,
  );

  const records = playable.map((m) => ({
    uuid: m.uuid,
    displayName: m.displayName,
    key: m.displayName.toLowerCase(),
    mapUrl: m.mapUrl,
    xMultiplier: m.xMultiplier,
    yMultiplier: m.yMultiplier,
    xScalarToAdd: m.xScalarToAdd,
    yScalarToAdd: m.yScalarToAdd,
    /** Width in meters covered by the full minimap image. */
    metersPerMinimap: 1 / (Math.abs(m.xMultiplier) * 100),
    callouts: (m.callouts ?? [])
      .filter(
        (c): c is ApiCallout & { location: ApiCalloutLocation } =>
          c.location != null,
      )
      .map((c) => ({
        regionName: c.regionName,
        superRegion: c.superRegionName ?? null,
        worldX: c.location.x,
        worldY: c.location.y,
      })),
  }));

  const banner =
    "// AUTO-GENERATED by scripts/sync-valorant-maps.ts. Do not edit by hand.\n";

  const fileContent =
    banner +
    "\n" +
    "export interface ValorantMapCallout {\n" +
    "  regionName: string;\n" +
    "  superRegion: string | null;\n" +
    "  worldX: number;\n" +
    "  worldY: number;\n" +
    "}\n\n" +
    "export interface ValorantMapRecord {\n" +
    "  uuid: string;\n" +
    "  displayName: string;\n" +
    "  key: string;\n" +
    "  mapUrl: string;\n" +
    "  xMultiplier: number;\n" +
    "  yMultiplier: number;\n" +
    "  xScalarToAdd: number;\n" +
    "  yScalarToAdd: number;\n" +
    "  /** How many meters of in-game space the minimap covers along its width. */\n" +
    "  metersPerMinimap: number;\n" +
    "  callouts: ValorantMapCallout[];\n" +
    "}\n\n" +
    `export const VALORANT_MAPS: readonly ValorantMapRecord[] = ${JSON.stringify(records, null, 2)};\n\n` +
    "export function findMapRecord(name: string): ValorantMapRecord | undefined {\n" +
    "  if (!name) return undefined;\n" +
    "  const key = name.toLowerCase();\n" +
    "  return (\n" +
    "    VALORANT_MAPS.find((m) => m.key === key) ||\n" +
    "    VALORANT_MAPS.find((m) => key.includes(m.key)) ||\n" +
    "    VALORANT_MAPS.find((m) => m.key.includes(key))\n" +
    "  );\n" +
    "}\n\n" +
    "/** Convert in-game world coords (Unreal Units) to a 0..1 fraction of the minimap. */\n" +
    "export function worldToMinimap(\n" +
    "  worldX: number,\n" +
    "  worldY: number,\n" +
    "  map: ValorantMapRecord,\n" +
    "): { x: number; y: number } {\n" +
    "  // API coordinates are cross-mapped: worldY drives minimapX via xMultiplier/xScalar,\n" +
    "  // and worldX drives minimapY via yMultiplier/yScalar.\n" +
    "  return {\n" +
    "    x: worldY * map.xMultiplier + map.xScalarToAdd,\n" +
    "    y: worldX * map.yMultiplier + map.yScalarToAdd,\n" +
    "  };\n" +
    "}\n";

  await mkdir(OUT_DIR, { recursive: true });
  await writeFile(OUT_FILE, fileContent, "utf8");
  console.log(`[map-sync] wrote ${records.length} maps to ${OUT_FILE}`);
}

main().catch((err) => {
  console.error("[map-sync] failed:", err);
  process.exit(1);
});
